MMIO_PROBES = (
    ("UVD_PGFSM_CONFIG", 0x0000, 1),
    ("UVD_PGFSM_STATUS", 0x0001, 1),
    ("UVD_POWER_STATUS", 0x0004, 1),
    ("CC_UVD_HARVESTING", 0x0007, 1),
    ("UVD_JPEG_POWER_STATUS", 0x000A, 1),
    ("UVD_MASTINT_EN", 0x0200, 1),
    ("UVD_STATUS", 0x026F, 1),
    ("UVD_VERSION", 0x05C9, 1),
    ("UVD_NO_OP", 0x05BF, 1),
    ("UVD_JPEG_CNTL", 0x0080, 0),
    ("UVD_JRBC_STATUS", 0x0109, 0),
)

KEY_REG_READBACK = [0x0900C234, 0x0900CB80, 0x0900C910, 0x0900C914,
                    0x09023234, 0x09300234, 0x0003E810, 0x0003E814]

def smn_read(smu, a):
    try:
        return smu.smn_read32(a)
    except Exception as e:
        return f"ERR:{type(e).__name__}"

def mmio_ladder(direct):
    out = {}
    for name, off, seg in MMIO_PROBES:
        mmio = ((enable_vcn.VCN_SEG1_DW if seg else enable_vcn.VCN_SEG0_DW) + off) * 4
        try:
            out[name] = direct.rd(mmio)
        except Exception as e:
            out[name] = f"ERR:{type(e).__name__}"
    return out

def main():
    t0 = time.time()
    print(f"=== A1 FULL GASKET REPLAY ({len(WRITES)} writes) ===", flush=True)
    smu = Bc250Smu()
    try:
        if not smu.alive():
            print("FATAL: SMU not alive", flush=True); return 1
        print("[*] SMU alive", flush=True)
        if not smu.secure_access_enabled():
            unlock.smu = smu
            unlock.unlock(smu)
            if not smu.secure_access_enabled():
                print("FATAL: secure SMU path did not open", flush=True); return 1
        print("[*] secure SMN path open", flush=True)

        direct = enable_vcn.VcnDirect()
        before = mmio_ladder(direct)
        rb_before = {a: smn_read(smu, a) for a in KEY_REG_READBACK}
        print("[*] MMIO before:", flush=True)
        for k, v in before.items():
            print(f"    {k} = {v if isinstance(v,str) else hex(v)}", flush=True)
        print("[*] SMN readback before:", flush=True)
        for a, v in rb_before.items():
            print(f"    {a:#010x} = {v if isinstance(v,str) else hex(v)}", flush=True)

        ok = 0
        for idx, (grp, a, v) in enumerate(WRITES):
            try:
                smu.smn_write32(a, v)
                ok += 1
            except Exception as e:
                print(f"WRITE FAIL [{idx}] {grp} {a:#010x} <- {v:#010x}: {e}", flush=True)
                break
            if idx % 200 == 199:
                if not smu.alive():
                    print(f"SMU DIED after {ok} writes", flush=True); return 4
                print(f"  [{ok}/{len(WRITES)}] t={time.time()-t0:.1f}s", flush=True)
        print(f"[*] writes done: {ok}/{len(WRITES)} t={time.time()-t0:.1f}s", flush=True)
        if not smu.alive():
            print("SMU DIED at end", flush=True); return 4

        time.sleep(1.0)
        after = mmio_ladder(direct)
        rb_after = {a: smn_read(smu, a) for a in KEY_REG_READBACK}
        print("[*] MMIO after:", flush=True)
        for k, v in after.items():
            b = before[k]
            mark = " <== CHANGED" if v != b else ""
            print(f"    {k} = {v if isinstance(v,str) else hex(v)}{mark}", flush=True)
        print("[*] SMN readback after:", flush=True)
        for a, v in rb_after.items():
            print(f"    {a:#010x} = {v if isinstance(v,str) else hex(v)}", flush=True)

        all_ones = all(isinstance(v,int) and v == 0xFFFFFFFF for v in after.values())
        any_alive = any(isinstance(v,int) and v != 0xFFFFFFFF for v in after.values())
        print(f"=== VERDICT: all_ones={all_ones} any_alive={any_alive} ===", flush=True)
        Path("/home/OWNER/vcn_unlock/full_replay_result.json").write_text(json.dumps({
            "ok_writes": ok, "mmio_before": before, "mmio_after": after,
            "smn_before": rb_before, "smn_after": rb_after,
            "all_ones": all_ones, "any_alive": any_alive,
            "t": round(time.time()-t0,1)}, indent=1))
        direct.rf.close(); os.close(direct.vram_fd)
        return 0 if any_alive else 2
    finally:
        smu.close()

if __name__ == "__main__":
    raise SystemExit(main())
